CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_distribute_relief` (IN `p_warehouse_id` INT, IN `p_area_id` INT, IN `p_organization_id` INT, IN `p_vehicle_id` INT, IN `p_item_id` INT, IN `p_quantity` DECIMAL(12,2), OUT `p_distribution_id` INT)   proc_body: BEGIN
    DECLARE v_available DECIMAL(12,2);

    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        RESIGNAL;
    END;

    START TRANSACTION;

    SELECT quantity INTO v_available
    FROM inventory
    WHERE warehouse_id = p_warehouse_id AND item_id = p_item_id
    FOR UPDATE;

    IF v_available IS NULL OR v_available < p_quantity THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'Insufficient inventory for this distribution';
    END IF;

    VALUES (p_warehouse_id, p_area_id, p_organization_id, p_vehicle_id, NOW());

    SET p_distribution_id = LAST_INSERT_ID();

    -- trg_distributionitem_after_insert automatically decrements Inventory
    VALUES (p_distribution_id, p_item_id, p_quantity);

    COMMIT;
END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_resolve_request` (IN `p_request_id` INT)   proc_body2: BEGIN
    DECLARE v_team_id INT;

    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        RESIGNAL;
    END;

    START TRANSACTION;

    SELECT assigned_team_id INTO v_team_id
    FROM emergencyrequest
    WHERE request_id = p_request_id
    FOR UPDATE;

    IF v_team_id IS NULL THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'Assign a rescue team before resolving this request';
    END IF;

    UPDATE emergencyrequest
    SET status = 'Resolved'
    WHERE request_id = p_request_id;

    UPDATE rescueteam
    SET status = 'Available'
    WHERE team_id = v_team_id;

    COMMIT;
END$$

