INSERT INTO `disaster` (`disaster_id`, `disaster_name`, `disaster_type`, `start_date`, `end_date`, `severity`, `description`) VALUES
(1, 'Cyclone Remal', 'Cyclone', '2026-05-26', '2026-05-29', 'Severe', 'Category 1 cyclone that made landfall on the Bangladesh-West Bengal coast, causing storm surges and widespread flooding in coastal districts.'),
(2, 'Monsoon Flood 2026', 'Flood', '2026-07-10', '2026-07-25', 'Catastrophic', 'Heavy monsoon rainfall and upstream water flow caused severe riverine flooding across northern districts.'),
(3, 'Cyclone Rimal Aftermath Flood', 'Flood', '2026-06-02', '2026-06-15', 'Moderate', 'Secondary flooding from tidal surge breaches following Cyclone Remal.');
